package dev.zomboid.clans;
import java.lang.reflect.Proxy;import java.util.function.Predicate;
public final class DebugPve {
 public static void register(Object event){Object literal=R.call(R.type("net.minecraft.commands.Commands"),"literal","clanpvetest");R.call(literal,"requires",(Predicate<Object>)source->R.yes(R.call(source,"hasPermission",2))&&R.type("net.minecraft.server.level.ServerPlayer").isInstance(R.call(source,"getEntity")));Class<?> command=R.type("com.mojang.brigadier.Command");Object execute=Proxy.newProxyInstance(command.getClassLoader(),new Class<?>[]{command},(proxy,method,args)->{if(method.getName().equals("run")){Object source=R.call(args[0],"getSource"),player=R.call(source,"getPlayerOrException");start(player);Object m=Clans.manager(R.call(player,"getServer")),f=Clans.mine(m,player);return f!=null&&Pve.waves.containsKey(Clans.fid(f))?1:0;}if(method.getName().equals("toString"))return "Clan PvE test command";if(method.getName().equals("hashCode"))return System.identityHashCode(proxy);return proxy==args[0];});R.call(literal,"executes",execute);R.call(R.call(event,"getDispatcher"),"register",literal);}
 public static void start(Object p){if(!R.yes(R.call(p,"hasPermissions",2))){Clans.say(p,"Prueba PvE: requiere permisos de operador (nivel 2).");return;}Object m=Clans.manager(R.call(p,"getServer")),f=Clans.mine(m,p);if(f==null||!Clans.authority(f,p)){Clans.say(p,"Debes ser jefe/comandante de un clan con nexo colocado.");return;}if(Pve.waves.containsKey(Clans.fid(f))){Clans.say(p,"Ya hay una defensa activa.");return;}ClanState.Profile profile=Clans.state(m).profile(Clans.fid(f));profile.pveNext=0;profile.offer=0;profile.offerEnd=Clans.now(R.call(p,"getServer"))+6000;Clans.dirty(m);Pve.action(p,true);}
}
